(function(){
const esc=e=>String(e??"").replace(/[&<>"']/g,e=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[e]));
const norm=e=>String(e||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9]/g,"").toUpperCase();
const same=(a,b)=>"function"==typeof sameTeamName?sameTeamName(a,b):norm(a)===norm(b);
const display=e=>"function"==typeof getDisplayName?getDisplayName(e):String(e||"");
const teamLogo=e=>{
    try{const laff="function"==typeof cffFindLAFFTeamInfo?cffFindLAFFTeamInfo(e):findLaffTeam(e);if(laff?.logo)return laff.logo}catch(a){}
    try{if(isSeaTeam(e)&&"function"==typeof resolveSEATeamLogo){const a=resolveSEATeamLogo(e);if(a&&"escudo.webp"!==a)return a}}catch(a){}
    return"function"==typeof cffResolveTeamLogoSafe?cffResolveTeamLogoSafe(e):"function"==typeof getTeamLogoSafe?getTeamLogoSafe(e):logos&&logos[e]||"escudo.webp";
};
const playerPhoto=e=>fastPlayerPhoto(e);
const roleLabel=e=>{const t=String(e||"").trim();if(!t)return"Jogador";const a=norm(t);return a.includes("GRAN")?"Granadeiro":a.includes("SUP")||a.includes("SNIPER")?"Suporte":a.includes("RUSH")?"Rusher":t};
const teamKey=e=>"function"==typeof getTeamCanonicalName?getTeamCanonicalName(e):String(e||"").trim();
let __cffStandardHistoryIndex=null,__cffStandardHistorySize=-1,__cffStandardPhotoKeyMap=null;

function fastPlayerPhoto(name){
    const raw=String(name||"").trim();
    if(!raw)return"silhueta.webp";
    if(!__cffStandardPhotoKeyMap){
        __cffStandardPhotoKeyMap=new Map;
        try{Object.keys(playerPhotos||{}).forEach(k=>__cffStandardPhotoKeyMap.set(norm(k),playerPhotos[k]))}catch(e){}
    }
    return playerPhotos&&playerPhotos[raw]||__cffStandardPhotoKeyMap.get(norm(raw))||"silhueta.webp";
}

function isSeaTeam(name){
    const n=String(name||"").trim();
    if(!n)return false;
    try{
        if("function"==typeof getSEATeamFullName){
            const full=getSEATeamFullName(n);
            if(full&&norm(full)!==norm(n))return true;
        }
    }catch(e){}
    return["BURIRAM UNITED ESPORTS","RRQ KAZU","ALL GAMERS GLOBAL","BIGETRON BY VITALITY","TWISTED MINDS","HEAVY","TEAM FALCONS","TEAM FLASH","ONIC OLYMPUS","SECRET WAG","AURORA GAMING","ACD","GAMXPE","GOW","SHADOW ESPORTS","AVIDA","EVOS DIVINE","P ESPORTS","ARGON MY","MAQNA ESPORTS"].some(e=>same(e,n));
}

function standardName(name){
    try{
        if(isSeaTeam(name)&&"function"==typeof getSEATeamFullName)return getSEATeamFullName(name);
        const laff="function"==typeof cffFindLAFFTeamInfo?cffFindLAFFTeamInfo(name):findLaffTeam(name);
        return laff?.name||teamKey(name)||name;
    }catch(e){return name}
}

function findLaffTeam(name){
    try{return(window.getLAFFTeams&&window.getLAFFTeams()||[]).find(e=>same(e.name,name)||same(e.time,name)||same(e.sigla,name))||null}catch(e){return null}
}

function findSeaTeam(name){
    try{
        const n=standardName(name);
        return(window.getSEAProfileTeams&&window.getSEAProfileTeams()||[]).find(e=>same(e.name,n)||same(e.sigla,n)||same(e.name,name)||same(e.sigla,name))||null;
    }catch(e){return null}
}

function getActivePlayers(name){
    const out=new Map,add=p=>{
        if(!p||!p.jogador&&!p.name)return;
        const jogador=String(p.jogador||p.name||"").trim();
        if(!jogador)return;
        const equipe=String(p.equipe||p.team||name||"").trim();
        if(!same(equipe,name))return;
        const left="function"==typeof cffPlayerHasLeftTeam&&cffPlayerHasLeftTeam(jogador,name);
        const inactive=p.isEx||p.ativo===false||["nao","não","false","0","inativo"].includes(String(p.ativo||"").toLowerCase())||left;
        if(inactive)return;
        out.set(norm(jogador),{jogador,role:p.role||p.funcao||p.posicao||playerRoles&&playerRoles[jogador]||"Jogador",captain:!!(p.capitao||playerCaptains&&playerCaptains[jogador])});
    };
    try{(db?.players||[]).forEach(add)}catch(e){}
    try{(window.getLAFFPlayers&&window.getLAFFPlayers()||[]).forEach(p=>add({jogador:p.name,equipe:p.team,role:p.role||p.funcao,ativo:p.active!==false}))}catch(e){}
    try{
        const sea=findSeaTeam(name);
        (sea?.players||[]).forEach(p=>add({jogador:p.cleanName||p.displayName||p.rawName,equipe:sea.name,role:p.funcao||p.role||"Jogador",ativo:true}));
    }catch(e){}
    try{
        (window.getSEAProfilePlayers&&window.getSEAProfilePlayers()||[]).forEach(p=>add({jogador:p.cleanName||p.displayName||p.rawName,equipe:p.team,role:p.funcao||p.role||"Jogador",ativo:true}));
    }catch(e){}
    try{
        const parsed=seaAbatesParsed&&Array.isArray(seaAbatesParsed.rows)?seaAbatesParsed.rows:[];
        parsed.forEach(row=>{
            const headers=seaAbatesParsed.headers||[];
            const ph="function"==typeof findSEAHeaderByType?findSEAHeaderByType(headers,"player"):headers.find(h=>/JOGADOR|PLAYER|NICK/i.test(h));
            if(!ph)return;
            const rh="function"==typeof findSEAHeaderByType?findSEAHeaderByType(headers,"role"):headers.find(h=>/FUN|ROLE|POS/i.test(h));
            const th="function"==typeof findSEAHeaderByType?findSEAHeaderByType(headers,"team"):headers.find(h=>/TIME|EQUIPE|TEAM/i.test(h));
            const jogador="function"==typeof cleanSEAPlayerName?cleanSEAPlayerName(row[ph]):row[ph];
            const equipe="function"==typeof getSEARowTeamName?getSEARowTeamName(row,ph,th):row[th]||name;
            add({jogador,equipe,role:rh?row[rh]:"Jogador",ativo:true});
        });
    }catch(e){}
    return[...out.values()].sort((a,b)=>String(a.jogador).localeCompare(String(b.jogador),"pt-BR"));
}

function getStaff(name){
    try{return(dbStaff||[]).filter(e=>same(e.equipe,name)).sort((a,b)=>String(a.cargo).localeCompare(String(b.cargo),"pt-BR"))}catch(e){return[]}
}

function playerCard(p,staff=false){
    const name=display(p.jogador||p.nome),photo=staff?(staffPhotos&&staffPhotos[p.nome]||staffPhotos&&staffPhotos[name]||"silhueta.webp"):playerPhoto(p.jogador||name),click=staff?`openStaffProfile('${String(p.nome||"").replace(/'/g,"\\'")}')`:`openPlayerProfile('${String(p.jogador||name).replace(/'/g,"\\'")}')`;
    return`<button type="button" class="${staff?"team-standard-staff":"team-standard-player"}" onclick="${click}" title="${esc(name)}">
        <span class="team-standard-avatar"><img src="${esc(photo)}" alt="${esc(name)}" loading="lazy" decoding="async" onerror="this.src='silhueta.webp'"></span>
        <strong>${esc(name)}</strong>
        <span class="team-standard-role">${esc(staff?p.cargo||"Staff":roleLabel(p.role))}</span>
    </button>`;
}

function ensureLayout(){
    const page=document.getElementById("team-profile");
    if(!page||page.dataset.standard==="1")return;
    page.dataset.standard="1";
    page.classList.add("team-standard-page");
    page.innerHTML=`
        <button class="btn-back" onclick="navigate(lastVisitedPage)">← Voltar</button>
        <section class="team-standard-hero">
            <img id="tp-logo" class="team-standard-logo" src="escudo.webp" alt="">
            <h1 id="tp-name" class="team-standard-name">NOME</h1>
            <span id="tp-status" class="team-standard-status">Equipe</span>
            <span id="tp-group" style="display:none;"></span>
            <span id="tp-pos" style="display:none;"></span>
            <button class="btn-action team-standard-results-btn" onclick="openResultsModal()">Ver todos os resultados</button>
            <div id="tp-next-match-container" style="width:100%;"></div>
        </section>
        <section class="team-standard-section">
            <div class="team-standard-section-head"><h3>Sobre</h3></div>
            <div id="tp-standard-about" class="team-standard-about"></div>
        </section>
        <section class="team-standard-section">
            <div class="team-standard-section-head"><h3>Jogadores e staff</h3></div>
            <div id="tp-players-cards-container" class="team-standard-roster"></div>
            <div id="tp-standard-staff" class="team-standard-staff-grid"></div>
        </section>
        <section class="team-standard-section">
            <div class="team-standard-section-head">
                <h3>Desempenho da equipe por torneio</h3>
                <button type="button" class="btn-action" onclick="cffToggleStandardTeamPerformance()">Ver competições</button>
            </div>
            <div id="tp-standard-performance" class="team-standard-performance-panel" hidden></div>
            <div id="tp-best-worst-container" style="display:none;"></div>
            <div id="tp-stats-container" style="display:none;"></div>
            <div id="tp-confrontation-result" style="display:none;"></div>
            <button id="btn-confrontation" style="display:none;" onclick="openConfrontationModal()"></button>
            <div id="tp-evolution-container" style="display:none;"><canvas id="team-evolution-chart"></canvas><div id="team-chart-summary"></div></div>
            <select id="tp-stage-filter" style="display:none;"><option value="geral">Geral</option><option value="classificatoria">Classificatória</option><option value="final">Final</option></select>
            <div id="tp-day-filters" style="display:none;"></div>
            <select id="tp-opp-group" style="display:none;"></select>
            <select id="chart-stage" style="display:none;"><option value="classificatoria">Classificatória</option><option value="final">Final</option></select>
            <select id="chart-metric" style="display:none;"><option value="pontos_dia">Pontos Totais por Dia</option></select>
            <table id="table-team-players" style="display:none;"><tbody></tbody></table>
        </section>
        <section class="team-standard-section"><div id="tp-player-history-mount"></div></section>
        <section class="team-standard-section">
            <div class="team-standard-section-head"><h3>Galeria de troféus</h3></div>
            <div id="tp-trophies-container" class="team-standard-trophies"></div>
        </section>`;
}

function renderAbout(name,active){
    const about=document.getElementById("tp-standard-about");
    if(!about)return;
    const region=isSeaTeam(name)?"asiática":"brasileira";
    about.innerHTML=`<strong>${esc(standardName(name))}</strong> é uma organização ${region} de Free Fire.${active?"":" A equipe não possui elenco ativo cadastrado no momento."}`;
}

function renderRoster(name){
    const players=getActivePlayers(name),staff=getStaff(name),box=document.getElementById("tp-players-cards-container"),staffBox=document.getElementById("tp-standard-staff"),status=document.getElementById("tp-status");
    const active=players.length>0;
    if(status)status.textContent=active?"Equipe ativa":"Equipe inativa";
    if(box)box.innerHTML=active?players.map(p=>playerCard(p)).join(""):'<div class="team-standard-empty">Equipe sem elenco ativo cadastrado.</div>';
    if(staffBox)staffBox.innerHTML=staff.length?`<div class="team-standard-staff-title">Staff</div>${staff.map(p=>playerCard(p,true)).join("")}`:"";
    return active;
}

function aggregateStats(name){
    const stages=["geral","classificatoria","final"],rows=[];
    stages.forEach(stage=>{
        let all=[];
        try{all=cffTeamProfileAggregateTeamRows(stage)||[]}catch(e){}
        const row=all.find(e=>same(e.equipe,name));
        if(row&&Number(row.quedas)>0)rows.push({stage,label:"final"===stage?"Final":"classificatoria"===stage?"Classificatória":"Geral",...row});
    });
    return rows;
}

function getTeamResultsRows(name){
    let rows=[];
    try{rows="function"==typeof getResultsByTeamAliases?getResultsByTeamAliases(name):dbResults&&dbResults[name]||[]}catch(e){rows=[]}
    try{if("function"==typeof getNovosTorneiosResultsForTeam)rows=[...rows,...getNovosTorneiosResultsForTeam(name)]}catch(e){}
    const seen=new Set;
    return rows.filter(r=>{const key=`${r.torneio||""}|${r.data||""}|${r.place||""}|${r.tier||""}`;if(seen.has(key))return false;seen.add(key);return true});
}

function performanceCards(name){
    const cards=[];
    const ffws=aggregateStats(name),geral=ffws.find(e=>"geral"===e.stage)||ffws[0];
    if(geral)cards.push({id:"ffws-br-2026",title:"FFWS Brasil 2026 Split 1",subtitle:`${Number(geral.pontos||0)} pts · ${Number(geral.quedas||0)} quedas registradas`,full:true,stats:geral});
    getTeamResultsRows(name).forEach((r,i)=>{
        const title=r.torneio||"Competição registrada";
        if(cards.some(c=>norm(c.title)===norm(title)))return;
        cards.push({id:`result-${i}`,title,subtitle:`${r.place||"-"} · ${r.tier||"Tier"}${r.data?` · ${r.data}`:""}`,result:r});
    });
    return cards;
}

function statGrid(row){
    return`<div class="team-standard-stat-grid">
        <div class="team-standard-stat"><small>Pontos</small><strong>${Number(row.pontos||0)}</strong></div>
        <div class="team-standard-stat"><small>Média de pontos</small><strong>${(Number(row.avg||0)||Number(row.pontos||0)/(Number(row.quedas||1))).toFixed(1)}</strong></div>
        <div class="team-standard-stat"><small>Abates</small><strong>${Number(row.abates||0)}</strong></div>
        <div class="team-standard-stat"><small>Booyahs</small><strong>${Number(row.booyah||0)}</strong></div>
        <div class="team-standard-stat"><small>Quedas jogadas</small><strong>${Number(row.quedas||0)}</strong></div>
        <div class="team-standard-stat"><small>Rank do confronto</small><strong>${row.rank?`${row.rank}º`:"-"}</strong></div>
    </div>`;
}

function resultDetails(r){
    return`<div class="team-standard-result-details">
        <div><small>Data</small><strong>${esc(r.data||"-")}</strong></div>
        <div><small>Tier</small><strong>${esc(r.tier||"-")}</strong></div>
        <div><small>Colocação</small><strong>${esc(String(r.place||"-").replace(/st|nd|rd|th/gi,"º"))}</strong></div>
        <div><small>Competição</small><strong>${esc(r.torneio||"-")}</strong></div>
    </div>`;
}

function stageRows(stage){
    try{return(cffTeamProfileAggregateTeamRows(stage)||[]).filter(e=>Number(e.quedas||0)>0).sort((a,b)=>Number(b.pontos||0)-Number(a.pontos||0)||Number(b.abates||b.kills||0)-Number(a.abates||a.kills||0))}catch(e){return[]}
}
function stageTeamRow(name,stage){return stageRows(stage).find(e=>same(e.equipe,name))||null}
function fmt(n,d=0){const v=Number(n||0);return Number.isFinite(v)?v.toFixed(d):d?(0).toFixed(d):"0"}
function dailyTeamRows(name,stage){
    const data="function"==typeof cffGetStageQuedas?cffGetStageQuedas(stage):dbQuedas,days=[];
    Object.entries(data||{}).forEach(([day,quedas])=>{
        let row={dia:Number(day)||day,pontos:0,abates:0,booyah:0,quedas:0,posTotal:0};
        Object.values(quedas||{}).forEach(q=>{
            const r=(q.resultados||[]).find(e=>same(e.equipe,name));
            if(!r)return;
            row.pontos+=(posPoints&&posPoints[r.posicao]||0)+(Number(r.kills)||0);
            row.abates+=Number(r.kills)||0;
            row.booyah+=Number(r.booyah)||0;
            row.quedas+=1;
            row.posTotal+=Number(r.posicao)||0;
        });
        if(row.quedas)days.push({...row,mediaPos:row.posTotal/row.quedas,mediaPts:row.pontos/row.quedas,mediaKills:row.abates/row.quedas});
    });
    return days.sort((a,b)=>Number(a.dia)-Number(b.dia));
}
function rankingPosition(name,stage){const rows=stageRows(stage),i=rows.findIndex(e=>same(e.equipe,name));return i>=0?i+1:null}
function standardAnalysisTable(rows,name){
    return`<div class="team-standard-analysis-table-wrap"><table class="team-standard-analysis-table"><thead><tr><th>#</th><th>Equipe</th><th>PTS</th><th>K</th><th>B!</th><th>Q</th><th>Media</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${same(r.equipe,name)?"is-current-team":""}"><td>${i+1}</td><td>${esc(shortNames&&shortNames[r.equipe]||r.equipe)}</td><td>${Number(r.pontos||0)}</td><td>${Number(r.abates||r.kills||0)}</td><td>${Number(r.booyah||r.booyahs||0)}</td><td>${Number(r.quedas||0)}</td><td>${fmt(Number(r.pontos||0)/(Number(r.quedas||1)),1)}</td></tr>`).join("")}</tbody></table></div>`;
}
function renderStandardFullAnalysis(name,stage="geral"){
    const row=stageTeamRow(name,stage),rows=stageRows(stage),daily=dailyTeamRows(name,stage),rank=rankingPosition(name,stage),best=daily.slice().sort((a,b)=>b.pontos-a.pontos)[0],worst=daily.slice().sort((a,b)=>a.pontos-b.pontos)[0],max=Math.max(1,...daily.map(e=>e.pontos));
    if(!row)return`<div class="team-standard-empty">Esta equipe nao possui dados completos nesta etapa.</div>`;
    return`<div class="team-standard-analysis">
        <div class="team-standard-analysis-toolbar"><strong>Analise completa</strong><select onchange="cffSetStandardAnalysisStage('${String(name).replace(/'/g,"\\'")}',this.value)"><option value="geral" ${"geral"===stage?"selected":""}>Geral</option><option value="classificatoria" ${"classificatoria"===stage?"selected":""}>Classificatoria</option><option value="final" ${"final"===stage?"selected":""}>Final</option></select></div>
        <div class="team-standard-stat-grid"><div class="team-standard-stat"><small>Classificacao interna</small><strong>${rank?rank+"o":"-"}</strong></div><div class="team-standard-stat"><small>Pontos</small><strong>${Number(row.pontos||0)}</strong></div><div class="team-standard-stat"><small>Media de pontos</small><strong>${fmt(Number(row.pontos||0)/(Number(row.quedas||1)),1)}</strong></div><div class="team-standard-stat"><small>Abates</small><strong>${Number(row.abates||row.kills||0)}</strong></div><div class="team-standard-stat"><small>Booyahs</small><strong>${Number(row.booyah||row.booyahs||0)}</strong></div><div class="team-standard-stat"><small>Quedas jogadas</small><strong>${Number(row.quedas||0)}</strong></div></div>
        <div class="team-standard-analysis-summary"><div><small>Melhor dia</small><strong>${best?`Dia ${best.dia} - ${best.pontos} pts`:"-"}</strong></div><div><small>Dia mais baixo</small><strong>${worst?`Dia ${worst.dia} - ${worst.pontos} pts`:"-"}</strong></div><div><small>Media de abates</small><strong>${fmt(Number(row.abates||row.kills||0)/(Number(row.quedas||1)),2)}</strong></div><div><small>Colocacao media</small><strong>${fmt(row.avgPos||row.mediaPos||row.somaPosicao/(Number(row.quedas||1)),2)}o</strong></div></div>
        <div class="team-standard-analysis-block"><h4>Grafico de pontuacao por dia</h4><div class="team-standard-bars">${daily.map(d=>`<div class="team-standard-bar-row"><span>Dia ${d.dia}</span><i><b style="width:${Math.max(4,Math.round(d.pontos/max*100))}%"></b></i><strong>${d.pontos} pts</strong></div>`).join("")||'<div class="team-standard-empty">Sem dados por dia.</div>'}</div></div>
        <div class="team-standard-analysis-block"><h4>Desempenho por confronto/dia</h4><div class="team-standard-day-grid">${daily.map(d=>`<div class="team-standard-day-card"><strong>Dia ${d.dia}</strong><span>${d.quedas} quedas</span><span>${d.pontos} pts</span><span>${d.abates} K</span><span>${fmt(d.mediaPos,2)}o pos. media</span></div>`).join("")||'<div class="team-standard-empty">Sem dados por queda.</div>'}</div></div>
        <div class="team-standard-analysis-block"><h4>Classificacao interna da etapa</h4>${standardAnalysisTable(rows,name)}</div>
    </div>`;
}
function renderPerformance(name){
    const panel=document.getElementById("tp-standard-performance");
    if(!panel)return;
    const cards=performanceCards(name);
    if(!cards.length){panel.innerHTML='<div class="team-standard-empty">Desempenho por torneio será exibido quando houver partidas registradas.</div>';return}
    panel.innerHTML=`<div class="team-standard-competition-grid">${cards.map(card=>`<article class="team-standard-competition-card ${card.full?"is-full-analysis":""}">
        <button type="button" class="team-standard-competition-toggle" onclick="cffToggleStandardCompetition('${card.id}','${String(name).replace(/'/g,"\\'")}',${card.full?"true":"false"})">
            <span><strong>${esc(card.title)}</strong><small>${esc(card.subtitle||"")}</small></span>
            <b>Ver dados</b>
        </button>
        <div id="team-standard-competition-${card.id}" class="team-standard-competition-details" hidden>${card.full?renderStandardFullAnalysis(name,"geral"):card.stats?statGrid(card.stats):resultDetails(card.result)}</div>
    </article>`).join("")}</div>`;
}

window.cffToggleStandardTeamPerformance=function(){
    const panel=document.getElementById("tp-standard-performance");
    if(!panel)return;
    panel.hidden=!panel.hidden;
    const btn=panel.closest(".team-standard-section")?.querySelector(".team-standard-section-head .btn-action");
    if(btn)btn.textContent=panel.hidden?"Ver competições":"Ocultar competições";
};
window.cffToggleStandardCompetition=function(id,name,full){const el=document.getElementById(`team-standard-competition-${id}`);if(!el)return;el.hidden=!el.hidden;if(full&&!el.hidden)el.innerHTML=renderStandardFullAnalysis(name||currentTeamView||"","geral")};
window.cffSetStandardAnalysisStage=function(name,stage){const el=document.getElementById("team-standard-competition-ffws-br-2026");if(el)el.innerHTML=renderStandardFullAnalysis(name||currentTeamView||"",stage||"geral")};

async function renderTeamPlayersHistoryStandard(name,opts={}){
    ensureLayout();
    const mount=document.getElementById("tp-player-history-mount");
    if(!mount)return;
    const expanded=!!opts.expanded;
    if(!opts.load){
        mount.innerHTML=`<div class="team-standard-section-head"><h3>Histórico dos jogadores</h3><button type="button" class="btn-action" onclick="cffLoadCompactTeamPlayersHistory('${String(name).replace(/'/g,"\\'")}')">Carregar histórico</button></div><div class="team-standard-empty">Histórico disponível sob demanda para manter a página leve.</div>`;
        return;
    }
    mount.innerHTML='<div class="team-player-history-loading-inline">Preparando histórico...</div>';
    try{
        if(!Array.isArray(dbPassagens)||!dbPassagens.length){
            if("function"==typeof cffLoadPassagensChunkedForTeamHistory)await cffLoadPassagensChunkedForTeamHistory();
            else if("function"==typeof loadPassagens)await loadPassagens();
        }
    }catch(e){}
    let players=getHistoryFastPlayers(name);
    if(!players.length){mount.innerHTML='<div class="team-standard-section-head"><h3>Histórico dos jogadores</h3></div><div class="team-standard-empty">Sem informação.</div>';return}
    const current=players.filter(e=>e.isCurrent).length,ex=players.length-current,list=expanded?players:players.slice(0,18);
    mount.innerHTML=`<div class="team-standard-section-head">
        <h3>Histórico dos jogadores</h3>
        <button type="button" class="btn-action" onclick="${expanded?`cffCollapseTeamPlayersHistory('${String(name).replace(/'/g,"\\'")}')`:`cffExpandTeamPlayersHistory('${String(name).replace(/'/g,"\\'")}')`}">${expanded?"Voltar ao compacto":"Expandir histórico com fotos"}</button>
    </div>
    <div class="team-player-history-stats" style="margin-bottom:14px;">
        <span><strong>${players.length}</strong><small>jogadores</small></span>
        <span><strong>${current}</strong><small>atuais</small></span>
        <span><strong>${ex}</strong><small>ex-jogadores</small></span>
    </div>
    <div class="${expanded?"team-standard-history-grid":"team-player-history-compact-grid"}">
        ${list.map(p=>expanded?`<button type="button" class="team-standard-history-card ${p.isCurrent?"is-current":"is-ex"}" onclick="${_safePPAttr(p.jogador)}">
            <span class="team-standard-avatar"><img src="${esc(playerPhoto(p.jogador||p.displayName))}" alt="${esc(p.displayName||p.jogador)}" loading="lazy" decoding="async" onerror="this.src='silhueta.webp'"></span>
            <strong>${esc(p.displayName||p.jogador)}</strong>
            <span class="team-standard-history-status">${p.isCurrent?"Atual":"Ex-jogador"}</span>
        </button>`:`<button type="button" class="team-player-history-compact-card ${p.isCurrent?"is-current":"is-inactive"}" onclick="${_safePPAttr(p.jogador)}">
            <span class="team-player-history-compact-name">${esc(p.displayName||p.jogador)}</span>
            <span class="team-player-history-compact-meta"><b>${p.isCurrent?"ATUAL":"EX-JOGADOR"}</b>${p.activeTeam&&!p.isCurrent?` · ${esc(p.activeTeam)}`:""}</span>
        </button>`).join("")}
    </div>
    ${players.length>list.length?`<div class="team-player-history-more">Mostrando ${list.length} de ${players.length} jogadores.</div>`:""}`;
}

function getHistoryFastPlayers(name){
    const idx=getHistoryIndex();
    const key=norm(teamKey(name));
    const direct=idx.get(key)||[];
    const active=getActivePlayers(name).map(p=>({jogador:p.jogador,displayName:display(p.jogador),isCurrent:true,abates:0,quedas:0}));
    const map=new Map;
    [...direct,...active].forEach(p=>{
        if(!p||!p.jogador)return;
        const k=norm(p.jogador);
        const prev=map.get(k)||{};
        map.set(k,{...prev,...p,isCurrent:!!(prev.isCurrent||p.isCurrent)});
    });
    return[...map.values()].sort((a,b)=>Number(b.isCurrent)-Number(a.isCurrent)||String(a.displayName||a.jogador).localeCompare(String(b.displayName||b.jogador),"pt-BR"));
}

function getHistoryIndex(){
    const size=Array.isArray(dbPassagens)?dbPassagens.length:0;
    if(__cffStandardHistoryIndex&&__cffStandardHistorySize===size)return __cffStandardHistoryIndex;
    const idx=new Map;
    (dbPassagens||[]).forEach(row=>{
        const jogador=row.jogador;
        if(!jogador)return;
        (row.passagens||[]).forEach(p=>{
            if(!p||!p.equipe||!String(p.cargo||"").toUpperCase().includes("JOGADOR"))return;
            const key=norm(teamKey(p.equipe));
            if(!key)return;
            const arr=idx.get(key)||[];
            arr.push({jogador,displayName:display(jogador),isCurrent:false,abates:0,quedas:0});
            idx.set(key,arr);
        });
    });
    __cffStandardHistoryIndex=idx;
    __cffStandardHistorySize=size;
    return idx;
}

function getHistoryFallbackPlayers(name){
    const map=new Map,add=p=>{
        if(!p||!p.jogador)return;
        const key=norm(p.jogador);
        if(!key)return;
        const prev=map.get(key)||{};
        map.set(key,{...prev,...p,isCurrent:!!(prev.isCurrent||p.isCurrent),abates:Math.max(Number(prev.abates||0),Number(p.abates||0)),quedas:Math.max(Number(prev.quedas||0),Number(p.quedas||0))});
    };
    try{
        (dbPassagens||[]).forEach(row=>{
            const pass=(row.passagens||[]).filter(p=>same(p.equipe,name)&&String(p.cargo||"").toUpperCase().includes("JOGADOR"));
            if(pass.length)add({jogador:row.jogador,displayName:display(row.jogador),isCurrent:false,abates:0,quedas:0});
        });
    }catch(e){}
    try{getActivePlayers(name).forEach(p=>add({jogador:p.jogador,displayName:display(p.jogador),isCurrent:true,abates:0,quedas:0}))}catch(e){}
    return[...map.values()].sort((a,b)=>Number(b.isCurrent)-Number(a.isCurrent)||String(a.displayName||a.jogador).localeCompare(String(b.displayName||b.jogador),"pt-BR"));
}

window.renderTeamPlayersHistory=renderTeamPlayersHistoryStandard;
window.cffExpandTeamPlayersHistory=e=>renderTeamPlayersHistoryStandard(e||currentTeamView,{expanded:true,load:true});
window.cffCollapseTeamPlayersHistory=e=>renderTeamPlayersHistoryStandard(e||currentTeamView,{expanded:false,load:true});
window.cffLoadCompactTeamPlayersHistory=e=>renderTeamPlayersHistoryStandard(e||currentTeamView,{expanded:false,load:true});

function standardTitleEvent(t){return t.event||t.tournament||t.torneio||t.competition||t.name||"Competicao"}
function standardTitleType(t){return t.type||t.award||t.premio||t.title||"Conquista"}
function standardTitleTeam(t){return t.team||t.equipe||t.time||""}
function standardTitleAliases(name){
    const set=new Set([norm(name),norm(standardName(name)),norm(teamKey(name))]);
    try{const a="function"==typeof getTeamAliasSet?getTeamAliasSet(name):null;a&&a.forEach(e=>set.add(norm(e)))}catch(e){}
    try{Object.entries(window.globalTeamAliasesMap||{}).forEach(([k,v])=>{(same(k,name)||same(v,name))&&(set.add(norm(k)),set.add(norm(v)))})}catch(e){}
    return set;
}
function standardTitleMatches(name,team){const aliases=standardTitleAliases(name),k=norm(team);return!!k&&(aliases.has(k)||same(team,name))}
function standardTitleLogo(t){
    const event=standardTitleEvent(t),direct=t.logo||t.logoUrl||t.logo_url||t.leagueLogo||t.imagem||"";
    if(direct)return direct;
    try{if("function"==typeof resolveLeagueLogo){const l=resolveLeagueLogo(event);if(l)return l}}catch(e){}
    try{if("function"==typeof otGetLeagueLogo){const l=otGetLeagueLogo({name:event});if(l)return l}}catch(e){}
    try{if(leagueLogos){const key=Object.keys(leagueLogos).find(k=>norm(k)===norm(event)||norm(event).includes(norm(k)));if(key&&leagueLogos[key])return leagueLogos[key]}}catch(e){}
    return norm(event).includes("LBFF")?"lbff.webp":"trofeu.webp";
}
function dedupeStandardTitles(list){const seen=new Set;return(list||[]).filter(t=>{const key=`${norm(standardTitleEvent(t))}|${norm(standardTitleType(t))}|${norm(standardTitleTeam(t))}|${norm(t.player||t.jogador||"")}`;if(seen.has(key))return false;seen.add(key);return true})}
function getStandardTeamTitles(name){
    let collective=[],individual=[];
    try{if("function"==typeof cffGetTeamTitles){const t=cffGetTeamTitles(name)||{};collective.push(...(t.collective||[]));individual.push(...(t.individual||[]))}}catch(e){}
    try{collective.push(...(titlesData?.coletivos||[]).filter(t=>standardTitleMatches(name,standardTitleTeam(t))))}catch(e){}
    try{individual.push(...(titlesData?.individuais||[]).filter(t=>standardTitleMatches(name,standardTitleTeam(t))))}catch(e){}
    try{if("function"==typeof getNovosTorneiosCollectiveTitlesForTeam)collective.push(...getNovosTorneiosCollectiveTitlesForTeam(name))}catch(e){}
    try{if("function"==typeof getNovosTorneiosIndividualAwardsForTeam)individual.push(...getNovosTorneiosIndividualAwardsForTeam(name))}catch(e){}
    try{const finalTitle="function"==typeof cffTeamProfileFinalTitleForTeam?cffTeamProfileFinalTitleForTeam(name):null;if(finalTitle)collective.unshift(finalTitle)}catch(e){}
    return{collective:dedupeStandardTitles(collective),individual:dedupeStandardTitles(individual)};
}
function hydrateStandardTrophies(name){
    if(window.__cffStandardTrophyHydrating)return;
    window.__cffStandardTrophyHydrating=true;
    const jobs=[];
    if("function"==typeof loadTitles)jobs.push(loadTitles().catch(()=>{}));
    if("function"==typeof loadNovosTorneios)jobs.push(loadNovosTorneios().catch(()=>{}));
    Promise.all(jobs).then(()=>renderStandardTrophies(name)).finally(()=>{window.__cffStandardTrophyHydrating=false;window.__cffStandardTrophyHydrated=true});
}
function renderStandardTrophies(name){
    const box=document.getElementById("tp-trophies-container");
    if(!box)return;
    const titles=getStandardTeamTitles(name),collective=titles.collective||[],individual=titles.individual||[];
    if(!collective.length&&!individual.length){
        box.innerHTML='<div class="team-standard-empty">Galeria de trofeus em breve.</div>';
        if(!window.__cffStandardTrophyHydrated)hydrateStandardTrophies(name);
        return;
    }
    const card=(t,type)=>`<div class="team-standard-trophy-card ${type}">
        <span class="team-standard-trophy-logo"><img src="${esc(standardTitleLogo(t))}" alt="${esc(standardTitleEvent(t))}" loading="lazy" decoding="async" onerror="this.src='trofeu.webp'"></span>
        <strong>${esc(standardTitleType(t))}</strong>
        <small>${esc(standardTitleEvent(t))}</small>
        ${t.player||t.jogador?`<em>${esc(t.player||t.jogador)}</em>`:""}
    </div>`;
    box.innerHTML=`${collective.length?`<div class="team-standard-trophy-group"><h4>Conquistas coletivas</h4><div class="team-standard-trophy-grid">${collective.map(t=>card(t,"collective")).join("")}</div></div>`:""}${individual.length?`<div class="team-standard-trophy-group"><h4>Premios individuais</h4><div class="team-standard-trophy-grid">${individual.map(t=>card(t,"individual")).join("")}</div></div>`:""}`;
    if(!window.__cffStandardTrophyHydrated)hydrateStandardTrophies(name);
}

window.renderTeamProfileStats=function(){
    ensureLayout();
    const raw=currentTeamView||document.getElementById("tp-name")?.textContent||"";
    const name=standardName(raw);
    currentTeamView=name;
    const logo=document.getElementById("tp-logo"),title=document.getElementById("tp-name");
    if(title)title.textContent=name;
    if(logo){logo.src=teamLogo(name);logo.alt=name;logo.style.display="block"}
    const active=renderRoster(name);
    renderAbout(name,active);
    renderPerformance(name);
    renderTeamPlayersHistoryStandard(name,{expanded:false,load:false});
    renderStandardTrophies(name);
};

const openTraditional=async name=>{
    if("function"==typeof loadTeamAliases)try{await loadTeamAliases()}catch(e){}
    if("function"==typeof window.loadLAFFData)try{await window.loadLAFFData()}catch(e){}
    if("function"==typeof window.loadSEAProfilesData)try{await window.loadSEAProfilesData()}catch(e){}
    if("function"==typeof window.loadSEAData)try{await window.loadSEAData(true)}catch(e){}
    if("function"==typeof loadMercado)try{await loadMercado({silent:true,skipPhotos:true})}catch(e){}
    try{await openTeamProfile(standardName(name))}catch(e){return false}
    return true;
};
window.openLAFFTeamProfile=openTraditional;
window.openSEATeamProfile=openTraditional;
window.cffOpenLAFFTeamInTraditionalProfile=openTraditional;
window.cffOpenStandardTeamProfile=openTraditional;

const previousSelectSearchResult=window.selectSearchResult;
window.selectSearchResult=function(type,name){
    if("laff-team"===type||"sea-team"===type){
        "function"==typeof window.navCloseSearchUI&&window.navCloseSearchUI();
        return openTraditional(name);
    }
    return"function"==typeof previousSelectSearchResult?previousSelectSearchResult(type,name):null;
};

const previousSEAHashRoute=window.cffResolveSEAHashRoute;
window.cffResolveSEAHashRoute=function(hash){
    const key=String(hash||"").replace(/^#/,"").trim();
    if(!key)return false;
    try{
        const direct="function"==typeof getSEATeamFullName?getSEATeamFullName(key):key;
        if(isSeaTeam(direct)){openTraditional(direct);return true}
    }catch(e){}
    return"function"==typeof previousSEAHashRoute?previousSEAHashRoute(hash):false;
};
})();
